INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Convertible dasselbe wie ein normales Notebook?', 2, '[{"text": "Nein", "correct": true, "because": "Convertible ist flexibel einsetzbar"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Bauweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bietet mir ein Convertible?', 3, '[{"text": "Dualer Einsatz", "correct": true, "because": "Laptop und Tablet in einem"}, {"text": "Höhere Leistung", "correct": false, "because": "Nicht primär"}, {"text": "Geringerer Preis", "correct": false, "because": "Oft teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren ein Convertible?', 5, '[{"text": "Touchscreen", "correct": true, "because": "Für Tablet-Modus nötig"}, {"text": "Dreh- oder Klappmechanismus", "correct": true, "because": "Ermöglicht Umstellung"}, {"text": "Externer Monitor", "correct": false, "because": "Nicht integriert"}, {"text": "Festplatte", "correct": false, "because": "Standard bei Laptops"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es hat einen Touchscreen. b) Es ist immer leichter als ein Laptop.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewicht variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Convertibles?', 4, '[{"text": "Scharnierqualität", "correct": false, "because": "Wichtig für Haltbarkeit"}, {"text": "Touchscreen-Funktion", "correct": false, "because": "Kernmerkmal"}, {"text": "Farbauswahl", "correct": true, "because": "Sekundär zur Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Convertible immer eine Tastatur hat?', 2, '[{"text": "Ja", "correct": true, "because": "Integriert oder abnehmbar"}, {"text": "Nein", "correct": false, "because": "Tastatur ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem passt typischerweise dazu?', 3, '[{"text": "Windows", "correct": true, "because": "Optimiert für Touch"}, {"text": "Linux", "correct": false, "because": "Weniger Touch-fokussiert"}, {"text": "DOS", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nutzungsszenarien unterstützt es?', 5, '[{"text": "Präsentationen", "correct": true, "because": "Tablet-Modus hilfreich"}, {"text": "Textverarbeitung", "correct": true, "because": "Laptop-Modus geeignet"}, {"text": "Serververwaltung", "correct": false, "because": "Nicht primär"}, {"text": "3D-Rendering", "correct": false, "because": "Leistungsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Convertibles sind für Mobilität. b) Sie haben immer SSDs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSDs nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz?', 4, '[{"text": "Touchscreen", "correct": false, "because": "Kernfunktion"}, {"text": "Tastatur", "correct": false, "because": "Für Laptop-Modus nötig"}, {"text": "Externer Projektor", "correct": true, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Convertible schwerer als ein Tablet?', 2, '[{"text": "Ja", "correct": true, "because": "Tastatur erhöht Gewicht"}, {"text": "Nein", "correct": false, "because": "Meist schwerer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware ist entscheidend?', 4, '[{"text": "Scharnier", "correct": true, "because": "Ermöglicht Flexibilität"}, {"text": "Touch-Display", "correct": true, "because": "Für Tablet-Modus"}, {"text": "CD-Laufwerk", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für kreative Arbeiten ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vielseitig einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Anschaffung?', 3, '[{"text": "Display-Qualität", "correct": true, "because": "Wichtig für Touch"}, {"text": "Maximaler Speicher", "correct": false, "because": "Kontextabhängig"}, {"text": "Lautstärke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es unterstützt Stift-Eingabe. b) Es ist immer teurer als Laptops.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preis variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzmöglichkeiten bietet es?', 5, '[{"text": "Notizen machen", "correct": true, "because": "Touch und Stift"}, {"text": "Programmieren", "correct": true, "because": "Laptop-Modus"}, {"text": "Serverhosting", "correct": false, "because": "Nicht geeignet"}, {"text": "Gaming", "correct": false, "because": "Leistungsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Scharnierhaltbarkeit", "correct": false, "because": "Entscheidend für Langlebigkeit"}, {"text": "Batterielaufzeit", "correct": false, "because": "Wichtig für Mobilität"}, {"text": "Tastaturbeleuchtung", "correct": true, "because": "Nice-to-have"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein Convertible immer einen Stift?', 3, '[{"text": "Nein", "correct": true, "because": "Optional, nicht Standard"}, {"text": "Ja", "correct": false, "because": "Modellabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob es für Büroarbeit geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel für viele Aufgaben"}, {"text": "Nein", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft macht es besonders?', 4, '[{"text": "Hybridfunktion", "correct": true, "because": "Laptop und Tablet"}, {"text": "Höhere CPU-Leistung", "correct": false, "because": "Nicht spezifisch"}, {"text": "Kleinere Größe", "correct": false, "because": "Variiert"}]');
